def gen(rng):
    def word(lo, hi, alpha):
        w = ''.join(rng.choice(alpha) for _ in range(rng.randint(lo, hi)))
        if rng.random() < 0.2:
            w = w.capitalize()
        return w

    seps = [' ', '  ', '.', '. ', ' .', '..', '   ', '. .', ' . ']

    def make(k, lo, hi, alpha):
        s = rng.choice(['', ' ', '.', '  '])
        for i in range(k):
            if i:
                s += rng.choice(seps)
            s += word(lo, hi, alpha)
        return s + rng.choice(['', ' ', '.', '. ', '..'])

    def big(lo, hi, alpha):
        parts, total = [], 0
        while True:
            w = word(lo, hi, alpha)
            sep = rng.choice(seps)
            if total + len(w) + len(sep) + 4 > 200000:
                break
            parts.append(w + sep)
            total += len(w) + len(sep)
        return ''.join(parts) + 'z'

    tests = ['a', 'A.', '.x.', ' hello ', 'ab cd', 'ab. cd. ab', '...abc...', 'The quick brown fox.',
             'Hi   there.Hello..  to  world.']
    for _ in range(40):
        alpha = rng.choice(['ab', 'abcdefghijklmnopqrstuvwxyz'])
        tests.append(make(rng.randint(1, 12), 1, rng.randint(1, 6), alpha))
    tests.append(big(1, 8, 'abcdefghijklmnopqrstuvwxyz'))
    tests.append(big(1, 3, 'ab'))
    tests.append(big(4, 4, 'abcdefghijklmnopqrstuvwxyz'))
    tests.append('q' * 199999)
    return tests

